import { RefObject, useMemo, useRef } from 'react';
import { mixpanel } from '@fiverr-private/obs';
import { useAnalyticAdapter } from '../analyticAdapter';
import type { BIMeta } from '../types';

export const useVideoMixpanelEvents = (videoRef: RefObject<HTMLVideoElement>, meta: BIMeta) => {
    const BIMeta = useRef(meta);
    const callbacks = useMemo(() => {
        const sendEvent = (eventName, props) => {
            const { videoName, pageName } = BIMeta.current;

            const base = {
                'Page name': pageName,
                'Video name': videoName,
            };

            return mixpanel.track(eventName, {
                ...base,
                ...props,
            });
        };

        const onPlay = () => {
            const { autoPlay, subtitleExist, subtitleLocale } = BIMeta.current;

            sendEvent('Video - Play', {
                'Auto play': autoPlay,
                'Subtitles exist': subtitleExist,
                'Subtitles language': subtitleLocale,
            });
        };

        const onPause = () => {
            const { autoPlay, subtitleExist, subtitleLocale } = BIMeta.current;

            sendEvent('Video - Pause', {
                'Auto play': autoPlay,
                'Subtitles exist': subtitleExist,
                'Subtitles language': subtitleLocale,
            });
        };

        const onWatched = () => {
            const { subtitleExist, subtitleLocale } = BIMeta.current;
            const { duration, currentTime } = videoRef.current || {};

            sendEvent('Video - Finished Watching', {
                'Watch duration': currentTime,
                'Video completed': duration === currentTime,
                'Subtitles exist': subtitleExist,
                'Subtitles language': subtitleLocale,
            });
        };

        const onMute = () => {
            const { subtitleLocale } = BIMeta.current;
            const { currentTime } = videoRef.current || {};

            sendEvent('Video - Mute', {
                'Watch duration': currentTime,
                'Subtitles language': subtitleLocale,
            });
        };

        const onUnmute = () => {
            const { subtitleLocale } = BIMeta.current;
            const { currentTime } = videoRef.current || {};

            sendEvent('Video - Unmute', {
                'Watch duration': currentTime,
                'Subtitles language': subtitleLocale,
            });
        };
        const onSubtitleChange = (locale) => {
            const { subtitleLocale } = BIMeta.current;

            sendEvent('Video - changed subtitles language', {
                'Subtitles language': locale,
                'Subtitles previous language': subtitleLocale,
            });
        };

        return {
            onPlay,
            onPause,
            onWatched,
            onMute,
            onUnmute,
            onSubtitleChange,
        };
    }, [videoRef, BIMeta]);

    useAnalyticAdapter(videoRef, callbacks);
};
